const escapeMdV2 = (s) =>
  String(s).replace(/([_*$begin:math:display$$end:math:display$()~`>#+\-=|{}.!\\])/g, '\\$1');

if (item.json.output) {
  item.json.output = escapeMdV2(item.json.output);
}

return item;

const original = String($json.content || '').trim();
const t = original
  .toLowerCase()
  .replace(/ё/g, 'е')
  .replace(/[«»"'`]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// IMPORTANT: no \b around Cyrillic words.
// JavaScript word-boundary semantics are unreliable for Cyrillic.
const deleteVerb =
  /(?:^|\s)(?:удал(?:и|ить|яй|яйте|ите)?|убер(?:и|ите|ать)?|сотр(?:и|ите|еть)?|стер(?:еть|и|ите)?|очист(?:и|ить|ите)?)(?:\s|$)/i.test(t)
  || /(?:^|\s)удал\w*/i.test(t)
  || /(?:^|\s)убер\w*/i.test(t)
  || /(?:^|\s)сотр\w*/i.test(t);

const foodContext =
  /(прием|приема|приемов|пищ|питан|рацион|еда|еду|еды|завтрак|обед|ужин|перекус|блюд|запис)/i.test(t);

const relativeContext =
  /(последн|предыдущ|сегодня|вчера|за день|весь день|всю еду|все питание|всё питание)/i.test(t);

const isDelete = deleteVerb && (foodContext || relativeContext);

if (!isDelete) {
  return [{json:{...$json,is_delete:false,delete_debug:{original,t,deleteVerb,foodContext,relativeContext}}}];
}

const numberWords = {
  'один':1,'одну':1,'первый':1,'первую':1,
  'два':2,'две':2,'второй':2,'вторую':2,
  'три':3,'третий':3,'третью':3,
  'четыре':4,'четвертый':4,'четвертую':4,
  'пять':5,'пятый':5,'пятую':5,
  'шесть':6,'шестой':6,'шестую':6,
  'семь':7,'седьмой':7,'седьмую':7,
  'восемь':8,'восьмой':8,'восьмую':8,
  'девять':9,'девятый':9,'девятую':9,
  'десять':10,'десятый':10,'десятую':10
};

function readCount(text) {
  const digit = text.match(/(?:^|\s)(\d{1,2})\s+(?:последн\w*\s+)?(?:прием|приема|приемов|запис)/i);
  if (digit) return Math.max(1, Math.min(20, Number(digit[1])));

  for (const [word,num] of Object.entries(numberWords)) {
    const rx = new RegExp(`(?:^|\\s)${word}(?:\\s+последн\\w*)?\\s+(?:прием|приема|приемов|запис)`, 'i');
    if (rx.test(text)) return num;
  }
  return 1;
}

let scope='last';
let delete_count=readCount(t);

// Whole day.
if (/(весь|всю|все|всё).*(день|питан|рацион|еда|еду)|(?:питан|рацион|еда|еду)\s+за\s+(сегодня|вчера)|за\s+(сегодня|вчера|день)/i.test(t)) {
  scope='day';
  delete_count=999;
}

// Explicit ordinal meal: "удали второй прием".
let ordinal=null;
for (const [word,num] of Object.entries(numberWords)) {
  if (['один','одну','два','две','три','четыре','пять','шесть','семь','восемь','девять','десять'].includes(word)) continue;
  if (new RegExp(`(?:^|\\s)${word}\\s+(?:прием|приема)`, 'i').test(t)) {
    ordinal=num;
    scope='ordinal';
    delete_count=1;
    break;
  }
}

const ordinalDigit=t.match(/(?:^|\s)(\d{1,2})(?:-?й|-?ый|-?ой)?\s+(?:прием|приема)/i);
if (ordinalDigit && !/последн/i.test(t)) {
  ordinal=Math.max(1,Number(ordinalDigit[1]));
  scope='ordinal';
  delete_count=1;
}

// Time-specific.
const tm=t.match(/(?:^|\s)([01]?\d|2[0-3])[:.](\d{2})(?:\s|$)/);
const time=tm ? `${String(tm[1]).padStart(2,'0')}:${tm[2]}` : null;
if (time) {
  scope='time';
  delete_count=1;
}

let day='today';
if (/(?:^|\s)вчера(?:\s|$)/i.test(t)) day='yesterday';

const dm=t.match(/(?:^|\s)(\d{1,2})[./-](\d{1,2})(?:[./-](\d{2,4}))?(?:\s|$)/);
let explicit_date=null;
if (dm) {
  let y=dm[3] ? Number(dm[3]) : new Date().getFullYear();
  if (y<100) y+=2000;
  explicit_date=`${y}-${String(dm[2]).padStart(2,'0')}-${String(dm[1]).padStart(2,'0')}`;
  day='explicit';
}

if (/последн/i.test(t) && scope!=='day' && scope!=='ordinal' && scope!=='time') {
  scope='last_n';
}

return [{json:{
  ...$json,
  is_delete:true,
  delete_scope:scope,
  delete_count,
  delete_day:day,
  delete_date:explicit_date,
  delete_ordinal:ordinal,
  delete_time:time,
  delete_original:original,
  delete_debug:{original,t,deleteVerb,foodContext,relativeContext}
}}];

const intent=$items('Detect delete request')[0].json;
const rows=items.map(i=>i.json).filter(x=>x&&x.id&&x.deleted!==true);

const p=n=>String(n).padStart(2,'0');

function moscowParts(value){
  const d=new Date(value);
  if(Number.isNaN(d.getTime())) return null;
  const parts=new Intl.DateTimeFormat('en-CA',{
    timeZone:'Europe/Moscow',
    year:'numeric',month:'2-digit',day:'2-digit',
    hour:'2-digit',minute:'2-digit',hour12:false
  }).formatToParts(d);
  const get=t=>parts.find(x=>x.type===t)?.value;
  return {
    date:`${get('year')}-${get('month')}-${get('day')}`,
    hour:Number(get('hour')),
    minute:Number(get('minute'))
  };
}

const nowParts=moscowParts(new Date());
const today=nowParts.date;
const noonUtc=new Date(`${today}T12:00:00Z`);
noonUtc.setUTCDate(noonUtc.getUTCDate()-1);
const yesterday=moscowParts(noonUtc).date;

let targetDay=today;
if(intent.delete_day==='yesterday') targetDay=yesterday;
if(intent.delete_day==='explicit'&&intent.delete_date) targetDay=intent.delete_date;

function rowDay(m){
  if(m.eaten_day) return String(m.eaten_day).slice(0,10);
  return moscowParts(m.eaten_at)?.date || '';
}

function sessions(list,gap=12){
  const sorted=[...list].sort((a,b)=>new Date(a.eaten_at)-new Date(b.eaten_at));
  const out=[];
  for(const m of sorted){
    const ts=new Date(m.eaten_at).getTime();
    const day=rowDay(m);
    const prev=out[out.length-1];
    const prevTs=prev?new Date(prev.at).getTime():0;
    const sameDay=prev && prev.day===day;
    if(prev && sameDay && (ts-prevTs)<=gap*60*1000){
      prev.rows.push(m);
      prev.at=m.eaten_at;
    }else{
      out.push({at:m.eaten_at,day,rows:[m]});
    }
  }
  return out;
}

const dayRows=rows
  .filter(x=>rowDay(x)===targetDay)
  .sort((a,b)=>new Date(a.eaten_at)-new Date(b.eaten_at));

const daySessions=sessions(dayRows);
const allSessions=sessions(rows);

let selectedSessions=[];
let description='';

if(intent.delete_scope==='day'){
  selectedSessions=daySessions;
  description=intent.delete_day==='today'
    ? 'всё питание за сегодня'
    : intent.delete_day==='yesterday'
      ? 'всё питание за вчера'
      : `всё питание за ${targetDay}`;
}else if(intent.delete_scope==='ordinal'){
  const idx=Number(intent.delete_ordinal||0)-1;
  if(daySessions[idx]) selectedSessions=[daySessions[idx]];
  description=`${intent.delete_ordinal}-й приём пищи за ${targetDay}`;
}else if(intent.delete_scope==='time'){
  const [hh,mm]=String(intent.delete_time||'').split(':').map(Number);
  const target=hh*60+mm;
  let best=null;
  for(const s of daySessions){
    const mp=moscowParts(s.at);
    if(!mp) continue;
    const diff=Math.abs((mp.hour*60+mp.minute)-target);
    if(!best||diff<best.diff) best={s,diff};
  }
  if(best&&best.diff<=90) selectedSessions=[best.s];
  description=`приём пищи около ${intent.delete_time} за ${targetDay}`;
}else{
  const count=Math.max(1,Math.min(20,Number(intent.delete_count||1)));
  selectedSessions=allSessions.slice(-count);
  const actual=selectedSessions.length;
  description=actual===1?'последний приём пищи':`${actual} последних приёма пищи`;
}

const selected=selectedSessions.flatMap((s,sessionIndex)=>
  s.rows.map(m=>({...m,_session_index:sessionIndex,_session_at:s.at}))
);

if(!selected.length){
  return [{json:{
    found:false,
    chat_id:intent.chat_id,
    session_id:intent.session_id,
    description,
    target_day:targetDay,
    count:0,
    session_count:0
  }}];
}

return selected.map((m,i)=>({json:{
  found:true,
  chat_id:intent.chat_id,
  session_id:intent.session_id,
  delete_id:m.id,
  dish:m.dish,
  eaten_at:m.eaten_at,
  target_day:targetDay,
  description,
  count:selected.length,
  session_count:selectedSessions.length,
  idx:i
}}));

const selected=$items('Select meals to delete').map(x=>x.json).filter(x=>x.found);
const first=selected[0];
const dishes=[...new Set(selected.map(x=>x.dish).filter(Boolean))];

const sessionCount=Number(first.session_count||1);
const positionCount=selected.length;

let what;
if(sessionCount===1){
  what='Удалил приём пищи ✅';
}else{
  what=`Удалил ${sessionCount} последних приёма пищи ✅`;
}

const preview=dishes.slice(0,5).join(', ');
const extra=dishes.length>5?` и ещё ${dishes.length-5}`:'';

return [{json:{
  chat_id:first.chat_id,
  session_id:first.session_id,
  count:positionCount,
  session_count:sessionCount,
  description:first.description,
  dishes,
  content:`${what}\n${preview}${extra}${preview?'\n':''}Больше не учитывается в рационе.`
}}];

const x=$json;
return [{json:{
  chat_id:x.chat_id,
  session_id:x.session_id,
  content:`Не нашёл подходящий приём для удаления.

Можно написать обычным текстом:
• «удали последний приём пищи»
• «удали два последних приёма пищи»
• «удали питание за сегодня»
• «удали второй приём сегодня»
• «удали приём в 14:30»`
}}];

const msg = $json.message || {};
const chat_id = msg.chat?.id;
const message_id = msg.message_id;
let text = String(msg.text || '').replace(/^\/v(?:@\w+)?\s*/i, '').trim();

if (!chat_id || !text) {
  throw new Error('Пустая команда /v');
}

// One time anywhere in the message applies to the entire meal.
const tm = text.match(/\b([01]?\d|2[0-3])[:.](\d{2})\b/);
const time = tm ? `${String(tm[1]).padStart(2,'0')}:${tm[2]}` : null;
if (tm) text = text.replace(tm[0], ' ');

// Preferred syntax: one food per line.
// Also accept semicolon and " + " as separators.
// Commas are only treated as separators when there are no line breaks.
let chunks;
if (/\n/.test(text)) {
  chunks = text.split(/\n+/);
} else if (/\s*;\s*|\s+\+\s+/.test(text)) {
  chunks = text.split(/\s*;\s*|\s+\+\s+/);
} else {
  // Compatibility with "/v food 100 g, food 2 150 g"
  chunks = text.split(/\s*,\s*(?=[A-Za-zА-Яа-яЁё])/);
}

const clean = chunks
  .map(x => x.replace(/^[\s•\-–—\d.)]+/, '').replace(/\s+/g, ' ').trim())
  .filter(Boolean)
  .slice(0, 12);

if (!clean.length) throw new Error('Нет позиций в /v');

const positions = clean.map((raw, idx) => {
  const gm = raw.match(/(?:^|\s)(\d+(?:[.,]\d+)?)\s*(кг|kg|г|гр|g|gram|grams)\b/i);
  let explicit_grams = null;
  if (gm) {
    const v = Number(gm[1].replace(',', '.'));
    explicit_grams = /кг|kg/i.test(gm[2]) ? Math.round(v * 1000) : Math.round(v);
  }

  return {
    idx,
    raw,
    explicit_grams
  };
});

return [{json:{
  chat_id,
  message_id,
  raw:text.trim(),
  time,
  positions,
  positions_json:JSON.stringify(positions),
  position_count:positions.length
}}];

const src=$items('Parse /v command')[0].json;
const cache=$items('Resolve /v cache')[0]?.json||{};
const cached=Array.isArray(cache.cached_items)?cache.cached_items:[];

let payload=$json.message?.content ?? $json.output ?? $json;
if(typeof payload==='string'){
  let s=payload.replace(/```json|```/gi,'').trim();
  const a=s.indexOf('{'),b=s.lastIndexOf('}');
  if(a>=0&&b>a)s=s.slice(a,b+1);
  try{payload=JSON.parse(s)}catch(_){payload={items:[]}}
}
const aiItems=Array.isArray(payload?.items)?payload.items:[];
const combined=[...cached,...aiItems];
const byIdx=new Map(combined.map(x=>[Number(x.idx),x]));
const hints=Array.isArray(src.positions)?src.positions:[];
if(!hints.length)throw new Error('Нет позиций /v');

const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Europe/Moscow'}));
const pad=n=>String(n).padStart(2,'0');
const time=src.time||`${pad(now.getHours())}:${pad(now.getMinutes())}`;
const eaten_at=`${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}T${time}:00+03:00`;

const result=[];
for(const hint of hints){
  const x=byIdx.get(Number(hint.idx))||{};
  const dish=String(x.dish||hint.raw||'').trim();
  let grams=hint.explicit_grams!=null?Number(hint.explicit_grams):Number(x.grams||0);
  if(!dish)continue;
  if(!(grams>0))grams=100;

  // If AI ignored the user-entered grams, rescale its macros to that exact mass
  // only when its returned grams are known.
  let kcal=Number(x.kcal||0),prot=Number(x.prot||0),fat=Number(x.fat||0),carb=Number(x.carb||0);
  const returnedGrams=Number(x.grams||0);
  if(hint.explicit_grams!=null&&returnedGrams>0&&returnedGrams!==grams&&x.nutrition_source!=='cache'){
    const factor=grams/returnedGrams;
    kcal*=factor;prot*=factor;fat*=factor;carb*=factor;
  }

  result.push({json:{
    chat_id:src.chat_id,message_id:src.message_id,idx:Number(hint.idx),
    dish,grams:Math.round(grams),
    kcal:Math.max(0,Math.round(kcal*10)/10),
    prot:Math.max(0,Math.round(prot*10)/10),
    fat:Math.max(0,Math.round(fat*10)/10),
    carb:Math.max(0,Math.round(carb*10)/10),
    eaten_at,
    nutrition_source:String(x.nutrition_source||'estimate'),
    weight_source:hint.explicit_grams!=null?'user':String(x.weight_source||'estimate'),
    source_url:String(x.source_url||''),source_title:String(x.source_title||''),
    cache_hit:String(x.nutrition_source||'')==='cache',
    expected_count:hints.length
  }});
}
if(!result.length)throw new Error('Не удалось разобрать позиции /v');

function quality(x){
  const g=Number(x.json.grams||0),k=Number(x.json.kcal||0);
  const p=Number(x.json.prot||0),f=Number(x.json.fat||0),c=Number(x.json.carb||0);
  const macroKcal=p*4+f*9+c*4;
  const delta=k>0&&macroKcal>0?Math.abs(k-macroKcal)/k:0;
  const per100=g>0?k/g*100:0;
  const bad=!(g>0)||!(k>0)||per100>1200;
  const check=!bad&&(delta>.28||per100<5);
  return {...x,json:{...x.json,included:!bad,quality:bad?'bad':check?'check':'ok'}};
}
return result.map(quality);

const built = $items('Build /v meal').map(i=>i.json).sort((a,b)=>Number(a.idx)-Number(b.idx));
const rows = built;
if(!rows.length) throw new Error('Нет сохранённых позиций');

const totals = rows.reduce((a,r)=>({
  kcal:a.kcal+Number(r.kcal||0),
  prot:a.prot+Number(r.prot||0),
  fat:a.fat+Number(r.fat||0),
  carb:a.carb+Number(r.carb||0)
}),{kcal:0,prot:0,fat:0,carb:0});

const r1=n=>Math.round(Number(n||0)*10)/10;
const lines=rows.map((r,i)=>{
  const source=r.nutrition_source==='web'?' 🌐':'';
  return `${i+1}. ${r.dish} — ~${Math.round(Number(r.grams||0))} г · ${Math.round(Number(r.kcal||0))} ккал${source}`;
});

const content =
`Сохранил ${rows.length} ${rows.length===1?'позицию':rows.length>=2&&rows.length<=4?'позиции':'позиций'}:\n\n`+
lines.join('\n')+
`\n\nИтого: ~${Math.round(totals.kcal)} ккал\nБ ${r1(totals.prot)} · Ж ${r1(totals.fat)} · У ${r1(totals.carb)}`;

return [{json:{
  chat_id:rows[0].chat_id,
  count:rows.length,
  content,
  kcal:Math.round(totals.kcal),
  prot:r1(totals.prot),
  fat:r1(totals.fat),
  carb:r1(totals.carb)
}}];

const msg = $json.message || {};
const chat_id = msg.chat?.id;
const message_id = msg.message_id;
let text = String(msg.text || '')
  .replace(/^\/(?:day|день)(?:@\w+)?\s*/i,'')
  .trim();

if(!chat_id || !text) throw new Error('Пустая сводка за день');

const sectionAliases = [
  {rx:/^(?:утро|завтрак)(?:\s*[:—-]?\s*(\d{1,2}[:.]\d{2}))?\s*:?\s*(.*)$/i, key:'morning', label:'Утро', defaultTime:'09:00'},
  {rx:/^(?:день|обед)(?:\s*[:—-]?\s*(\d{1,2}[:.]\d{2}))?\s*:?\s*(.*)$/i, key:'day', label:'День', defaultTime:'14:00'},
  {rx:/^(?:вечер|ужин)(?:\s*[:—-]?\s*(\d{1,2}[:.]\d{2}))?\s*:?\s*(.*)$/i, key:'evening', label:'Вечер', defaultTime:'19:00'},
  {rx:/^(?:перекус)(?:\s*[:—-]?\s*(\d{1,2}[:.]\d{2}))?\s*:?\s*(.*)$/i, key:'snack', label:'Перекус', defaultTime:'16:30'}
];

const lines=text.split(/\n+/).map(x=>x.trim()).filter(Boolean);
let current=null;
const positions=[];

function addFood(raw, section){
  const cleaned=String(raw||'').replace(/^[•\-–—\d.)]+\s*/,'').trim();
  if(!cleaned) return;
  const gm=cleaned.match(/(?:^|\s)(\d+(?:[.,]\d+)?)\s*(кг|kg|г|гр|g)\b/i);
  let explicit_grams=null;
  if(gm){
    const v=Number(gm[1].replace(',','.'));
    if(Number.isFinite(v)&&v>0) explicit_grams=/кг|kg/i.test(gm[2])?Math.round(v*1000):Math.round(v);
  }
  positions.push({
    idx:positions.length,
    raw:cleaned,
    explicit_grams,
    meal_key:section.key,
    meal_label:section.label,
    meal_time:section.time
  });
}

for(const line of lines){
  let header=null;
  for(const def of sectionAliases){
    const m=line.match(def.rx);
    if(m){
      const rawTime=m[1]?m[1].replace('.',':'):def.defaultTime;
      const [hh,mm]=rawTime.split(':').map(Number);
      const valid=hh>=0&&hh<=23&&mm>=0&&mm<=59;
      header={key:def.key,label:def.label,time:valid?`${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}`:def.defaultTime};
      current=header;
      if(m[2]) addFood(m[2],current);
      break;
    }
  }
  if(header) continue;

  // If user omitted headings entirely, keep it as one evening meal.
  if(!current) current={key:'evening',label:'Вечер',time:'19:00'};

  // Within a section semicolon and " + " may separate foods; commas remain part of a food description.
  const parts=line.split(/\s*;\s*|\s+\+\s+/).filter(Boolean);
  for(const part of parts) addFood(part,current);
}

if(!positions.length) throw new Error('В сводке нет еды');
if(positions.length>30) positions.length=30;

const meals=[...new Map(positions.map(p=>[p.meal_key, {key:p.meal_key,label:p.meal_label,time:p.meal_time}])).values()];

return [{json:{
  chat_id,
  message_id,
  raw:text,
  positions,
  positions_json:JSON.stringify(positions),
  position_count:positions.length,
  meals,
  meal_count:meals.length
}}];

const src=$items('Parse day summary')[0].json;
let payload=$json.message?.content ?? $json.output ?? $json;
if(typeof payload==='string'){
  let s=payload.replace(/```json|```/gi,'').trim();
  const a=s.indexOf('{'),b=s.lastIndexOf('}');
  if(a>=0&&b>a)s=s.slice(a,b+1);
  try{payload=JSON.parse(s)}catch(_){throw new Error('Невалидный JSON дневной сводки')}
}

const returned=Array.isArray(payload?.items)?payload.items:[];
const byIdx=new Map(returned.map(x=>[Number(x.idx),x]));
const hints=Array.isArray(src.positions)?src.positions:[];
if(!hints.length)throw new Error('Нет позиций');

const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Europe/Moscow'}));
const pad=n=>String(n).padStart(2,'0');
const date=`${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;

const rows=[];
for(const h of hints){
  const x=byIdx.get(Number(h.idx))||{};
  const dish=String(x.dish||h.raw||'').trim();
  if(!dish)continue;
  let grams=h.explicit_grams!=null?Number(h.explicit_grams):Number(x.grams||0);
  if(!(grams>0))grams=100;
  rows.push({json:{
    chat_id:src.chat_id,
    message_id:src.message_id,
    idx:Number(h.idx),
    dish,
    grams:Math.round(grams),
    kcal:Math.max(0,Number(x.kcal||0)),
    prot:Math.max(0,Number(x.prot||0)),
    fat:Math.max(0,Number(x.fat||0)),
    carb:Math.max(0,Number(x.carb||0)),
    eaten_at:`${date}T${h.meal_time}:00+03:00`,
    meal_key:h.meal_key,
    meal_label:h.meal_label,
    meal_time:h.meal_time,
    nutrition_source:String(x.nutrition_source||'estimate'),
    weight_source:h.explicit_grams!=null?'user':String(x.weight_source||'estimate'),
    source_url:String(x.source_url||''),
    source_title:String(x.source_title||''),
    expected_count:hints.length
  }});
}
if(!rows.length)throw new Error('Не удалось разобрать дневную сводку');
return rows;

const rows=$items('Build day meals').map(i=>i.json).sort((a,b)=>a.meal_time.localeCompare(b.meal_time)||a.idx-b.idx);
if(!rows.length)throw new Error('Нет распознанных позиций');

const groups=new Map();
for(const r of rows){
  r.included = r.included !== false;
  if(!groups.has(r.meal_key))groups.set(r.meal_key,{label:r.meal_label,time:r.meal_time,rows:[]});
  groups.get(r.meal_key).rows.push(r);
}

const sum=arr=>arr.reduce((a,r)=>({
  kcal:a.kcal+Number(r.kcal||0),
  prot:a.prot+Number(r.prot||0),
  fat:a.fat+Number(r.fat||0),
  carb:a.carb+Number(r.carb||0)
}),{kcal:0,prot:0,fat:0,carb:0});
const r1=n=>Math.round(Number(n||0)*10)/10;

const blocks=[];
for(const g of groups.values()){
  const t=sum(g.rows);
  blocks.push(
    `🍽 *${g.label}* · ${g.time}\n`+
    g.rows.map((r,i)=>`${i+1}. ${r.dish} — ~${Math.round(r.grams)} г · ${Math.round(r.kcal)} ккал`).join('\n')+
    `\nИтого: ${Math.round(t.kcal)} ккал`
  );
}
const total=sum(rows);

return [{json:{
  chat_id:rows[0].chat_id,
  message_id:rows[0].message_id,
  count:rows.length,
  meal_count:groups.size,
  items:rows,
  items_json:JSON.stringify(rows),
  content:
    `*Сводка за день готова*\n\n`+
    blocks.join('\n\n')+
    `\n\n*За день:* ~${Math.round(total.kcal)} ккал\n`+
    `Б ${r1(total.prot)} · Ж ${r1(total.fat)} · У ${r1(total.carb)}\n\n`+
    `Проверь данные перед сохранением.`
}}];

const rows=$items('Build /v meal').map(i=>i.json).sort((a,b)=>Number(a.idx)-Number(b.idx));
if(!rows.length)throw new Error('Нет распознанных позиций');

const totals=rows.filter(r=>r.included!==false).reduce((a,r)=>({
  kcal:a.kcal+Number(r.kcal||0),prot:a.prot+Number(r.prot||0),
  fat:a.fat+Number(r.fat||0),carb:a.carb+Number(r.carb||0)
}),{kcal:0,prot:0,fat:0,carb:0});
const r1=n=>Math.round(Number(n||0)*10)/10;

const lines=rows.map((r,i)=>{
  const q=r.quality==='bad'?'⚠️ ':r.quality==='check'?'△ ':r.cache_hit?'⚡ ':'';
  const suffix=r.included===false?' · не учитываю':r.quality==='check'?' · проверь':'';
  return `${i+1}. ${q}${r.dish} — ~${Math.round(r.grams)} г · ${Math.round(r.kcal)} ккал${suffix}`;
});

return [{json:{
  chat_id:rows[0].chat_id,
  message_id:rows[0].message_id,
  count:rows.length,
  items:rows,
  items_json:JSON.stringify(rows),
  content:
    `*Проверь приём пищи*\\n\\n${lines.join('\\n')}\\n\\n`+
    `*Итого учтено:* ~${Math.round(totals.kcal)} ккал\\n`+
    `Б ${r1(totals.prot)} · Ж ${r1(totals.fat)} · У ${r1(totals.carb)}`+
    (rows.some(r=>r.cache_hit)?`\\n\\n⚡ Часть позиций взята из Food Cache без AI-поиска.`:'')
}}];

const src=$items('Parse /v command')[0].json;
let rows=$json;
if(!Array.isArray(rows)){
  if(Array.isArray(rows?.body))rows=rows.body;
  else if(Array.isArray(rows?.data))rows=rows.data;
  else rows=[];
}

const byIdx=new Map(rows.map(x=>[Number(x.idx),x]));
const cached=[];
const unresolved=[];

for(const p of src.positions||[]){
  const hit=byIdx.get(Number(p.idx));
  if(!hit){
    unresolved.push(p);
    continue;
  }

  const grams=p.explicit_grams!=null
    ? Number(p.explicit_grams)
    : Number(hit.typical_grams||0);

  if(!(grams>0)){
    unresolved.push(p);
    continue;
  }

  const factor=grams/100;
  const scale=v=>Math.round(Number(v||0)*factor*10)/10;

  cached.push({
    idx:Number(p.idx),
    dish:String(hit.display_name||p.raw),
    grams:Math.round(grams),
    kcal:scale(hit.kcal_per_100),
    prot:scale(hit.prot_per_100),
    fat:scale(hit.fat_per_100),
    carb:scale(hit.carb_per_100),
    nutrition_source:'cache',
    weight_source:p.explicit_grams!=null?'user':'cache',
    source_url:'',
    source_title:`Food Cache · ${Number(hit.use_count||0)} использ.`,
    cache_confidence:Number(hit.confidence||0)
  });
}

return [{json:{
  ...src,
  cached_items:cached,
  cache_hits:cached.length,
  unresolved_positions:unresolved,
  positions:unresolved,
  positions_json:JSON.stringify(unresolved),
  needs_ai:unresolved.length>0
}}];

const msg=$json.message||{};
const text=String(msg.text||'').trim();
const chat_id=msg.chat?.id;
const first_name=msg.from?.first_name||'';
const m=text.match(/^\/([a-zA-Z_]+)(?:@\w+)?(?:\s|$)/);
const cmd=m?m[1].toLowerCase():'';

const known=new Set([
  'start','help','today','add','delete','progress','profile','weight','summary','history',
  'subscription','settings','support','cancel','day','recommend','plan','shop','restaurant',
  'quick','sweet','training','overate','bedtime','can','why','checkin'
]);

return [{json:{
  ...$json,
  command:known.has(cmd)?cmd:'',
  is_command:known.has(cmd),
  chat_id,
  first_name
}}];
